    // Initialize the minimum time required to collect all apples at node 0
    int minTime = 0;
    // Create a boolean array to keep track of visited nodes
    boolean[] visited = new boolean[n];
    // Create a queue to store the nodes to be visited
    Queue<Integer> queue = new LinkedList<>();
    // Mark the starting node as visited
    visited[0] = true;
    // Enqueue the starting node
    queue.add(0);

    while (!queue.isEmpty()) {
        // Dequeue a node from the queue
        int node = queue.poll();
        // If the current node has an apple, add 2 to the minimum time
        if (hasApple[node]) {
            minTime += 2;
        }
        // Iterate through the edges of the current node
        for (int[] edge : edges) {
            // If the destination node has not been visited, mark it as visited and enqueue it
            if (!visited[edge[1]]) {
                visited[edge[1]] = true;
                queue.add(edge[1]);
            }
        }
    }

    // If not all nodes have been visited, return -1
    for (int i = 0; i < n; i++) {
        if (!visited[i]) {
            return -1;
        }
    }

    // Return the minimum time required to collect all apples and return to node 0
    return minTime;
}
